    "code": {"type": "string", "default": "import datetime\nimport json\nimport re\nWD = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMO = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = ['2026-10-30', '2026-11-02', '2026-11-20', '2026-12-24', '2026-12-25', '2026-12-31']\ndef parse_now(v):\n    s = str(v or '').strip().replace(' ', 'T').rstrip('Z')\n    for f, n in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:n], f)\n        except ValueError:\n            pass\n    raise ValueError('now')\ndef isbd(d):\n    return d.weekday() < 5 and d.isoformat() not in HOL\ndef nbd(d):\n    d = d + datetime.timedelta(days=1)\n    while not isbd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\ndef sp(d):\n    return WD[d.weekday()].title() + ' ' + str(d.day) + ' ' + MO[d.month - 1].title()\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    hm = now.strftime('%H:%M')\n    parts = []\n    if isbd(today) and hm < '18:00':\n        if hm >= '09:00':\n            parts.append('today, ' + sp(today) + ' (' + today.isoformat() + '), at a time later than ' + hm + ' and no later than 18:00')\n        else:\n            parts.append('today, ' + sp(today) + ' (' + today.isoformat() + '), from 09:00 to 18:00')\n    n = nbd(today)\n    parts.append(sp(n) + ' (' + n.isoformat() + '), from 09:00 to 18:00')\n    vars['callback_window_text'] = 'Now it is ' + sp(today) + ', ' + hm + '. A callback can be booked only ' + ' or '.join(parts) + ', both ends included. Any other day or time is outside the window.'\n    vars['today_spoken'] = sp(today)\nexcept Exception:\n    vars['callback_window_text'] = 'A callback can be booked only for the next business day from 09:00 to 18:00.'\n    vars['today_spoken'] = ''\nvars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\nvars['id_state'] = 'open'\n"},
