  "next_offer": {
   "name": "next_offer", "node_type": "code", "passthrough": true, "passthrough_default_transition": "offer", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": true,
   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
