   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
    "code": {"type": "string", "default": "import datetime\nimport json\nimport re\nWD = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMO = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = ['2026-10-30', '2026-11-02', '2026-11-20', '2026-12-24', '2026-12-25', '2026-12-31']\ndef parse_now(v):\n    s = str(v or '').strip().replace(' ', 'T').rstrip('Z')\n    for f, n in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:n], f)\n        except ValueError:\n            pass\n    raise ValueError('now')\ndef isbd(d):\n    return d.weekday() < 5 and d.isoformat() not in HOL\ndef nbd(d):\n    d = d + datetime.timedelta(days=1)\n    while not isbd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\ndef addbd(d, n):\n    for _ in range(n):\n        d = nbd(d)\n    return d\ndef lastbd_week(d):\n    mon = d - datetime.timedelta(days=d.weekday())\n    x = mon + datetime.timedelta(days=4)\n    while x >= mon:\n        if isbd(x):\n            return x\n        x = x - datetime.timedelta(days=1)\n    return None\ndef sp(d):\n    return WD[d.weekday()].title() + ' ' + str(d.day) + ' ' + MO[d.month - 1].title()\ndef money(a):\n    return '{:,.2f}'.format(round(float(a), 2))\ndef as_list(value):\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\ndef list_from_vars(vars, name, prefixes):\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = dict()\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            idx, _, field = str(key)[len(start):].partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), dict())[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    p = items[0]\n    days = int(float(p.get('days_past_due') or 0))\n    bands = [(1, 10, 10, 1, 'soft'), (11, 30, 6, 2, 'firm'), (31, 60, 3, 1, 'final')]\n    b = bands[-1] if days > 60 else next((x for x in bands if x[0] <= days <= x[1]), bands[0])\n    dl = addbd(today, b[2])\n    wk = lastbd_week(today)\n    if wk is None or wk <= today:\n        wk = lastbd_week(today + datetime.timedelta(days=7))\n    a1 = min(wk, dl) if wk else dl\n    t = str(p.get('type') or '')\n    if t == 'credit_card':\n        name = 'credit card ending ' + str(p.get('card_ending') or '')\n        floor = p.get('min_due')\n    elif t == 'overdraft':\n        name = 'overdraft'\n        floor = p.get('min_due')\n    else:\n        name = 'personal loan'\n        floor = p.get('monthly_instalment')\n    overdue = round(float(p.get('overdue_amount') or 0), 2)\n    floor = round(float(floor or 0), 2)\n    f = dict(pid=str(p.get('product_id') or ''), name=name, overdue=overdue, floor=floor, deadline=dl.isoformat(), a1=a1.isoformat(), attempts=b[3], today=today.isoformat())\n    vars['facts_json'] = json.dumps(f)\n    debt = 'Thank you. I am calling from the collections team about a late payment on your ' + name + '. The past-due amount is ' + money(overdue) + ', and it is ' + str(days) + ' days late.'\n    vars['debt_text'] = debt\n    vars['offer_text'] = debt + ' Can you make this payment today?'\n    rows = []\n    for i in range(0, 22):\n        d = today + datetime.timedelta(days=i)\n        rows.append(sp(d) + ' (' + d.isoformat() + '): ' + ('business day' if isbd(d) else 'NOT a business day') + (', within the deadline' if d <= dl else ', after the deadline'))\n    vars['facts_text'] = ('Today is ' + sp(today) + ' (' + today.isoformat() + '). Product: ' + name + '. Past due: ' + money(overdue) + ', ' + str(days) + ' days late. Lowest amount that can be recorded: ' + money(floor) + '. Latest date that can be recorded: ' + sp(dl) + ' (' + dl.isoformat() + '). Bank holidays: 30 October, 2 November, 20 November, 24, 25 and 31 December.\\nCalendar:\\n' + '\\n'.join(rows))\n    vars['cur_amount'] = str(overdue)\n    vars['cur_date'] = today.isoformat()\n    vars['refusals'] = '0'\n    vars['floor_offered'] = 'no'\n    vars['too_much'] = 'no'\n    vars['vague_asked'] = 'no'\n    vars['refused_json'] = '[]'\n    vars['offer_answer'] = 'stay'\n    vars['readback_text'] = ''\n    vars['close_outcome'] = 'no_promise'\n    vars['close_reason'] = 'refused'\n    vars['facts_state'] = 'ok' if f['pid'] else 'error'\nexcept Exception:\n    vars['facts_json'] = '{}'\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['offer_text'] = 'I am sorry, I cannot see your details right now.'\n    vars['facts_state'] = 'error'\n"},
