      if not str(key).startswith(start):\n                continue\n            idx, _, field = str(key)[len(start):].partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), dict())[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    p = items[0]\n    days = int(float(p.get('days_past_due') or 0))\n    bands = [(1, 10, 10, 1, 'soft'), (11, 30, 6, 2, 'firm'), (31, 60, 3, 1, 'final')]\n    b = bands[-1] if days > 60 else next((x for x in bands if x[0] <= days <= x[1]), bands[0])\n    dl = addbd(today, b[2])\n    wk = lastbd_week(today)\n    if wk is None or wk <= today:\n        wk = lastbd_week(today + datetime.timedelta(days=7))\n    a1 = min(wk, dl) if wk else dl\n    t = str(p.get('type') or '')\n    if t == 'credit_card':\n        name = 'credit card ending ' + str(p.get('card_ending') or '')\n        floor = p.get('min_due')\n    elif t == 'overdraft':\n        name = 'overdraft'\n        floor = p.get('min_due')\n    else:\n        name = 'personal loan'\n        floor = p.get('monthly_instalment')\n    overdue = round(float(p.get('overdue_amount') or 0), 2)\n    floor = round(float(floor or 0), 2)\n    f = dict(pid=str(p.get('product_id') or ''), name=name, overdue=overdue, floor=floor, deadline=dl.isoformat(), a1=a1.isoformat(), attempts=b[3], today=today.isoformat())\n    vars['facts_json'] = json.dumps(f)\n    debt = 'Thank you. I am calling from the collections team about a late payment on your ' + name + '. The past-due amount is ' + 