   "task_message": "You are not speaking with the customer. Do not say why you are calling and say nothing about any account, even if they offer to pay. Ask when {{title}} {{last_name}} can be reached. {{callback_window_text}} When the person gives a day and time inside that window, call schedule_callback with date as YYYY-MM-DD and time as HH:MM. If the day or time is outside the window, ask once for another time inside it; if that one is also outside, do not schedule: thank them, say goodbye and call end_call.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "schedule_callback", "handler": "__function__:api_call", "description": "Book a callback. CALL it as soon as the person gives a day and time inside the window.", "parameters": {"type": "object", "properties": {
      "url": {"type": "string", "default": "https://bank-mock.invalid/f1-nordhavn/v1/schedule_callback"},
      "method": {"type": "string", "default": "POST"},
      "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
      "body": {"type": "object", "required": ["customer_id", "date", "time"], "properties": {
       "customer_id": {"type": "string", "default": "{{customer_id}}"},
       "date": {"type": "string", "description": "The callback day as YYYY-MM-DD, inside the window.", "default": "{{date}}"},
       "time": {"type": "string", "description": "The callback time as HH:MM, 24-hour, inside the window.", "default": "{{time}}"}}}}}},
     "pre_process_code": "try:\n    b = config.get('body')\n    if isinstance(b, dict):\n        t = str(b.get('time') or '').strip().replace('.', ':')\n        if t.isdigit():\n            t = t + ':00'\n        if ':' in t:\n            h, m = t.split(':', 1)\n            b['time'] = h.strip().zfill(2) + ':' + m.strip()[:2].zfill(2)\n        b['date'] = str(b.get('date') or '').strip()[:10]\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['close_outcome'] = 'not_reached'\n        vars['close_reason'] = 'callback'\n        vars['call_state'] = 'callback_booked'\n        d['what_to_do_next'] = 'Booked. Thank them and say goodbye.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'Not booked. Ask once for another time inside the window.'\n    else:\n        result['what_to_do_next'] = 'Not booked. Ask once for another time inside the window.'\nexcept Exception:\n    pass\n"},
