    "code": {"type": "string", "default": "import datetime\nimport json\nimport re\nWD = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMO = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = ['2026-10-30', '2026-11-02', '2026-11-20', '2026-12-24', '2026-12-25', '2026-12-31']\nORD = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth', 'thirteenth', 'fourteenth', 'fifteenth', 'sixteenth', 'seventeenth', 'eighteenth', 'nineteenth', 'twentieth']\ndef parse_now(v):\n    s = str(v or '').strip().replace(' ', 'T').rstrip('Z')\n    for f, n in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:n], f)\n        except ValueError:\n            pass\n    raise ValueError('now')\ndef isbd(d):\n    return d.weekday() < 5 and d.isoformat() not in HOL\ndef nbd(d):\n    d = d + datetime.timedelta(days=1)\n    while not isbd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\ndef sp(d):\n    return WD[d.weekday()].title() + ' ' + str(d.day) + ' ' + MO[d.month - 1].title()\ndef money(a):\n    return '{:,.2f}'.format(round(float(a), 2))\ndef week_monday(d):\n    return d - datetime.timedelta(days=d.weekday())\ndef weekday_in_week(d, name, ahead=0):\n    return week_monday(d) + datetime.timedelta(days=7 * int(ahead) + WD.index(name))\ndef parse_date_words(s, today):\n    m = re.search(r'(\\d{4})-(\\d{1,2})-(\\d{1,2})', s)\n    if m:\n        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))\n    m = re.search(r'\\b(\\d{1,2})[./](\\d{1,2})[./](\\d{2,4})\\b', s)\n    if m:\n        y = int(m.group(3))\n        return datetime.date(y + 2000 if y < 100 else y, int(m.group(2)), int(m.group(1)))\n    for i, name in enumerate(MO):\n        m = re.search(r'\\b(\\d{1,2})(st|nd|rd|th)?\\s+(of\\s+)?' + name[:3] + r'[a-z]*\\b', s) or re.search(r'\\b' + name[:3] + r'[a-z]*\\s+(the\\s+)?(\\d{1,2})(st|nd|rd|th)?\\b', s)\n        if m:\n            day = int(m.group(1) if m.group(1) and m.group(1).isdigit() else m.group(2))\n            cand = datetime.date(today.year, i + 1, day)\n            return cand if cand >= today else datetime.date(today.year + 1, i + 1, day)\n    return None\ndef ordinals_to_digits(text):\n    s = str(text or '').lower()\n    s = re.sub(r'\\bthirty[\\s-]+first\\b', '31th', s)\n    s = re.sub(r'\\bthirtieth\\b', '30th', s)\n    for i, w in enumerate(ORD[:9], 1):\n        s = re.sub(r'\\btwenty[\\s-]+' + w + r'\\b', str(20 + i) + 'th', s)\n    for i, w in enumerate(ORD, 1):\n        s = re.sub(r'\\b' + w + r'\\b', str(i) + 'th', s)\n    return s\ndef resolve_date_words(text, today):\n    s = ordinals_to_digits(str(text or '').strip().lower())\n    if not s:\n        return None\n    ex = parse_date_words(s, today)\n    if ex is not None:\n        return ex\n    m = re.search(r'\\b(\\d{1,2})(st|nd|rd|th)\\b', s)\n    if m:\n        day = int(m.group(1))\n        for k in range(0, 3):\n            y, mo = today.year + (today.month - 1 + k) // 12, (today.month - 1 + k) % 12 + 1\n            try:\n                cand = datetime.date(y, mo, day)\n            except ValueError:\n                continue\n            if cand >= today:\n                return cand\n        return None\n    if 'day after tomorrow' in s:\n        return today + datetime.timedelta(days=2)\n    if 'tomorrow' in s:\n        return today + datetime.timedelta(days=1)\n    if re.search(r'\\btoday\\b|\\bnow\\b', s):\n        return today\n    for name in WD:\n        if re.search(r'\\b' + name + r'\\b', s):\n            if re.search(r'\\bnext\\s+' + name, s):\n                return weekday_in_week(today, name, 1)\n            if re.search(r'\\bthis\\s+' + name, s):\n                return weekday_in_week(today, name, 0)\n            d = weekday_in_week(today, name, 0)\n            return d if d >= today else d + datetime.timedelta(days=7)\n    return None\ntry:\n    today = parse_now(vars.get('now')).date()\n    f = json.loads(vars.get('facts_json') or '{}')\n    D = datetime.date.fromisoformat\n    floor = float(f['floor'])\n    overdue = float(f['overdue'])\n    dl = D(f['deadline'])\n    words = str(vars.get('agreed_date_words') or '').strip()\n    raw = str(vars.get('agreed_amount') or '').strip().replace(',', '')\n    try:\n        amount = float(raw) if raw else float(vars.get('cur_amount') or overdue)\n    except ValueError:\n        amount = float(vars.get('cur_amount') or overdue)\n    amount = round(min(amount, overdue), 2)\n    if words:\n        day = resolve_date_words(words, today)\n    else:\n        day = D(vars.get('cur_date') or f['today'])\n    vars['store_state'] = 'corrected'\n    show = amount if amount >= floor else floor\n    if day is None:\n        if vars.get('vague_asked') != 'yes':\n            vars['vague_asked'] = 'yes'\n            vars['cur_amount'] = str(amount)\n            vars['offer_text'] = 'Which exact day could you make the payment?'\n        else:\n            vars['cur_amount'] = str(show)\n            vars['cur_date'] = dl.isoformat()\n            vars['offer_text'] = 'The latest date I can record is ' + sp(dl) + '. Could you pay ' + money(show) + ' on ' + sp(dl) + '?'\n    elif day > dl:\n        vars['cur_amount'] = str(show)\n        vars['cur_date'] = dl.isoformat()\n        vars['offer_text'] = 'The latest date I can record is ' + sp(dl) + '. Could you pay ' + money(show) + ' on ' + sp(dl) + '?'\n    elif day < today or not isbd(day):\n        if day < today:\n            nb = today if isbd(today) else nbd(today)\n        else:\n            nb = nbd(day)\n        if nb > dl:\n            nb = dl\n        vars['cur_amount'] = str(show)\n        vars['cur_date'] = nb.isoformat()\n        vars['offer_text'] = 'I can only record a business day from today on. Could you pay ' + money(show) + ' on ' + sp(nb) + '?'\n    elif amount < floor - 0.001:\n        if vars.get('floor_offered') != 'yes':\n            vars['floor_offered'] = 'yes'\n            vars['cur_amount'] = str(floor)\n            vars['cur_date'] = day.isoformat()\n            vars['offer_text'] = 'I cannot record that amount. The lowest amount I can record is ' + money(floor) + ', and the rest stays overdue. Could you pay ' + money(floor) + ' on ' + sp(day) + '?'\n        else:\n            vars['cur_amount'] = str(amount)\n            vars['cur_date'] = day.isoformat()\n            vars['offer_answer'] = 'refused'\n            vars['store_state'] = 'refuse'\n    else:\n        vars['cur_amount'] = str(amount)\n        vars['cur_date'] = day.isoformat()\n        vars['readback_text'] = 'To confirm: for your ' + f['name'] + ', a payment of ' + money(amount) + ' on ' + sp(day) + '. Do you confirm?'\n        vars['store_state'] = 'stored'\nexcept Exception:\n    vars['offer_text'] = 'Which exact day could you make the payment?'\n    vars['store_state'] = 'corrected'\ntry:\n    vars['agreed_amount'] = ''\n    vars['agreed_date_words'] = ''\n    if vars.get('store_state') != 'refuse':\n        vars['offer_answer'] = 'stay'\n    vars['confirm_answer'] = 'stay'\nexcept Exception:\n    pass\n"},
