   "pre_actions": [{"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Hand the call to the support team.", "parameters": {"type": "object", "properties": {
