     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = str(b.get('answer') or '').strip()\n        if b.get('field') == 'phone_last4':\n            b['answer'] = re.sub(r'\\D', '', a)[-4:]\n        elif b.get('field') == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                b['answer'] = '%04d-%02d-%02d' % (int(m.group(3)), int(m.group(2)), int(m.group(1)))\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'All questions passed. Say thank you in a few words.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Do not mention any account details.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the date of birth again with the month as a word. This does not count as a wrong answer.'\n        elif str(d.get('ok')).lower() == 'false' and d.get('wrong_answers_left') is None:\n            d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'\n        else:\n            d['what_to_do_next'] = 'That answer does not match. Ask the same question once more.'\n    else:\n        result['what_to_do_next'] = 'The check did not work. Ask for the same answer again.'\nexcept Exception:\n    pass\n"},
